    editCard(deck,card){const box=el('div','ak-card');const front=el('textarea');front.placeholder='Mặt trước';front.setAttribute('aria-label','Mặt trước');front.value=card?.front||'';const back=el('textarea');back.placeholder='Mặt sau';back.setAttribute('aria-label','Mặt sau');back.value=card?.back||'';const reverse=el('input');reverse.type='checkbox';const label=el('label');label.append(reverse,document.createTextNode(' Tạo thêm thẻ đảo chiều'));box.append(el('h2','',card?'Sửa thẻ':'Thêm thẻ'),front,back);if(!card)box.append(label);box.append(button('Lưu',()=>{if(!front.value.trim()||!back.value.trim())return;if(card){card.front=front.value.trim();card.back=back.value.trim()}else{deck.cards.push(mk(front.value.trim(),back.value.trim()));if(reverse.checked)deck.cards.push(mk(back.value.trim(),front.value.trim()))}this.save(this.state.data)},'ak-primary'),button('Hủy',()=>this.render()));root.replaceChildren(box);front.focus();}
