  const app=new App();window.WordLabAnkis={open:()=>app.init(),backup:()=>{app.init();if(app.state.data)app.setState({screen:'backup'})},stats:()=>app.stats(),peek:()=>{if(app.state.data)return app.stats();try{const d=JSON.parse(localStorage.getItem(app.KEY));if(!valid(d))return null;const counts=d.decks.map(x=>app.deckCounts(x));return {decks:d.decks.length,cards:d.decks.reduce((s,x)=>s+x.cards.length,0),fresh:counts.reduce((s,x)=>s+x.n,0),due:counts.reduce((s,x)=>s+x.l+x.due,0),today:d.log?.[app.todayStr()]||0};}catch{return null}}};
  window.addEventListener('storage',e=>{if((e.key===app.KEY||e.key===null)&&app.rawSaved!==undefined&&e.newValue!==app.rawSaved){app.conflict=true;app.message='Ankis đã thay đổi ở tab khác. Hãy xuất JSON nếu có thay đổi chưa lưu, rồi tải lại trang.';app.render()}});
